CREATE TABLE doorways (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, owner_id TEXT NOT NULL REFERENCES owners(id), recipient_id TEXT NOT NULL REFERENCES owners(id), source_publication_id TEXT NOT NULL REFERENCES publications(id), target_publication_id TEXT NOT NULL REFERENCES publications(id), offer_id TEXT NOT NULL, source_json TEXT NOT NULL, question TEXT NOT NULL, entry_json TEXT NOT NULL, review_json TEXT NOT NULL, created_at INTEGER NOT NULL, decision TEXT CHECK(decision IN ('accepted','declined')), decided_at INTEGER, withdrawn_at INTEGER, UNIQUE(owner_id,offer_id));
CREATE INDEX doorways_recipient ON doorways(recipient_id,seq);
